    def tseitin_formula(depth):
        if depth == 1:
            return ['x']
        else:
            subformulas = [tseitin_formula(depth - 1) for _ in range(2)]
            new_var = f'x{depth}'
            return [f'({sub[0]} & {sub[1]}) -> {new_var}' for sub in zip(subformulas, subformulas)] + [f'{new_var}']

    def resolution_tree(formula):
